    public static function key(string $source):string{return'editorial_hub_'.substr(hash('sha256',$source),0,24);}
    public static function messages(string $locale):array{$en=explode('-',$locale,2)[0]==='en';$out=[];foreach(self::ENGLISH as$s=>$t)$out[self::key($s)]=$en?$t:$s;return$out;}
    public static function text(string $source,array $messages,array $values=[]):string{$source=match($source){'Gültige Empfängerseite und Version verwenden.'=>'Seite prüfen.','Ungültiges Textfeld.'=>'Suchangaben prüfen.',default=>$source};$text=$messages[self::key($source)]??$messages[SocialPlanningMessages::key($source)]??ManagerMessages::text($source,$messages);foreach($values as$key=>$value)$text=str_replace('{'.$key.'}',(string)$value,$text);return$text;}
